using HRIS.Api.Common; using HRIS.Api.DTOs.Letter; using HRIS.Api.Exceptions; using HRIS.Api.Models; using HRIS.Api.Models.Enums; using HRIS.Api.Repositories;
namespace HRIS.Api.Services; public class LetterService : ILetterService { private readonly ILetterRepository _repo; private readonly IReferenceRepository _refs; private readonly IApprovalService _approval; private readonly IAuditLogService _audit; private readonly IDocumentRepository _documents; public LetterService(ILetterRepository repo,IReferenceRepository refs,IApprovalService approval,IAuditLogService audit,IDocumentRepository documents){_repo=repo;_refs=refs;_approval=approval;_audit=audit;_documents=documents;} public async Task<List<LetterTypeResponseDto>> GetTypesAsync(bool includeInactive=false){if(!includeInactive) return (await _repo.GetTypesAsync()).Select(ToType).ToList(); return (await _repo.GetTypesAsync(true)).Select(ToType).ToList();} public async Task<LetterTypeResponseDto> SaveTypeAsync(int id,LetterTypeCreateDto dto,UserContext actor){if(!actor.IsHrOrSupport)throw new ForbiddenException("Hanya HR/Support yang boleh mengelola jenis surat."); if(dto.TemplateDocumentId is not null&&!await _refs.ExistsAsync<Document>(dto.TemplateDocumentId.Value))throw new BadRequestException("TemplateDocumentId tidak ditemukan."); LetterType x;if(id==0)x=await _repo.AddTypeAsync(new LetterType{Name=dto.Name.Trim(),TemplateDocumentId=dto.TemplateDocumentId});else{x=await _repo.GetTypeByIdAsync(id)??throw new NotFoundException("Jenis surat tidak ditemukan.");x.Name=dto.Name.Trim();x.TemplateDocumentId=dto.TemplateDocumentId;await _repo.UpdateTypeAsync(x);} if(actor.IsSupport)await _audit.LogAsync(actor.UserId,id==0?"LetterType.Create":"LetterType.Update",nameof(LetterType),x.Id,x.Name); return ToType(x);} public async Task<List<LetterRequestResponseDto>> GetRequestsAsync(UserContext actor){var rows=await _repo.GetRequestsAsync(actor.IsHrOrSupport?null:actor.EmployeeId);var apps=await _approval.GetByRefsAsync(ApprovalRequestTypes.Letter,rows.Select(x=>x.Id),actor);return rows.Select(x=>ToDto(x,apps.GetValueOrDefault(x.Id)?.Id)).ToList();} public async Task<LetterRequestResponseDto> CreateAsync(LetterRequestCreateDto dto,UserContext actor){var emp=actor.EmployeeId??throw new ForbiddenException("Akun ini tidak terhubung ke Employee.");var type=await _repo.GetTypeByIdAsync(dto.LetterTypeId)??throw new BadRequestException("Jenis surat tidak ditemukan.");if(!type.IsActive)throw new BadRequestException("Jenis surat tidak aktif.");var x=await _repo.AddRequestAsync(new LetterRequest{EmployeeId=emp,LetterTypeId=dto.LetterTypeId,Purpose=dto.Purpose.Trim(),Destination=dto.Destination?.Trim(),Status="Pending"});var app=await _approval.SubmitAsync(ApprovalRequestTypes.Letter,x.Id,emp,$"Permintaan surat {type.Name} untuk {x.Purpose}");return ToDto(await _repo.GetRequestByIdAsync(x.Id)!,app.Id);} public async Task IssueAsync(int id,int documentId,UserContext actor){if(!actor.IsHrOrSupport)throw new ForbiddenException("Hanya HR/Support yang boleh menerbitkan surat.");var x=await _repo.GetRequestByIdAsync(id)??throw new NotFoundException("Permintaan surat tidak ditemukan.");if(x.Status!="Approved")throw new BadRequestException("Surat hanya dapat diterbitkan setelah approval selesai.");var doc=await _documents.GetByIdAsync(documentId);if(doc is null||!doc.IsActive)throw new BadRequestException("DocumentId tidak ditemukan.");if(doc.OwnerEmployeeId!=x.EmployeeId)throw new BadRequestException("Dokumen hasil surat harus dimiliki oleh karyawan pengaju.");x.IssuedDocumentId=documentId;x.IssuedAt=DateTime.UtcNow;x.Status="Issued";await _repo.UpdateRequestAsync(x);if(actor.IsSupport)await _audit.LogAsync(actor.UserId,"Letter.Issue",nameof(LetterRequest),id,$"Dokumen {documentId}");} public static LetterRequestResponseDto ToDto(LetterRequest x,int? aid)=>new(){Id=x.Id,EmployeeId=x.EmployeeId,EmployeeName=x.Employee?.FullName??"",LetterTypeId=x.LetterTypeId,LetterTypeName=x.LetterType?.Name??"",Purpose=x.Purpose,Destination=x.Destination,Status=x.Status,IssuedDocumentId=x.IssuedDocumentId,IssuedAt=x.IssuedAt,CreatedAt=x.CreatedAt,ApprovalId=aid}; private static LetterTypeResponseDto ToType(LetterType x)=>new(){Id=x.Id,Name=x.Name,TemplateDocumentId=x.TemplateDocumentId,IsActive=x.IsActive}; }
